function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      console.log(count);
    }, 1000);
    return () => clearInterval(id);
  }, []); // Empty dependency array

  return <button onClick={() => setCount(c => c + 1)}>+</button>;
}

