function createWallet() {
  let balance = 100;
  return {
    deduct: (amount) => {
      balance -= amount;
      console.log(`Remaining: ${balance}`);
    }
  };
}

const myWallet = createWallet();
myWallet.balance = 9999; // 試圖直接修改
myWallet.deduct(20);

